export type RepoState = {
  name: string
  path: string
  branch: string
  dirty: number
  ahead: number
  hasUpstream: boolean
}

export type Snapshot = {
  scannedAt: number
  total: number
  repos: RepoState[]
}

declare module 'claude-code' {
  interface PluginState {
    'repo-band': {
      snapshot: Snapshot | null
      isScanning: boolean
      pendingExit: boolean
      isHidden: boolean
    }
  }
}
export type Job = {
  name: string
  lastRun: string | null
  result: number | null
  nextRun: string | null
}

export type JobReport = {
  checkedAt: number
  jobs: Job[]
  errorLines: number
  evalStatus: string | null
}

declare module 'claude-code' {
  interface PluginState {
    'job-watch': { report: JobReport | null }
  }
}
