        name: String(r.name),
        lastRun: typeof r.lastRun === 'string' ? r.lastRun : null,
        result: typeof r.result === 'number' ? r.result : null,
        nextRun: typeof r.nextRun === 'string' ? r.nextRun : null,
      }))
  } catch {
