import os

M = os.path.expanduser('~/.claude/mods')


def patch(rel, pairs):
    p = os.path.join(M, rel)
    s = open(p, encoding='utf-8').read()
    for a, b in pairs:
        assert a in s, (rel, a[:70])
        s = s.replace(a, b, 1)
    open(p, 'w', encoding='utf-8', newline='\n').write(s)


