    ("""// One edit's effect on the pending list. `before` is the edited file before
// the edit (null when new), `twin` the twin's text, `after` the edited file now.
export function track(list: Drift[], path: string, twin: string, before: string | null, twinText: string, after: string): Drift[] {
  const key = pairKey(path, twin)
  const old = list.find(d => d.key === key)
  const rest = list.filter(d => d.key !== key)
  if (after === twinText) return rest
  // Both sides edited this turn: copying either way would drop an edit.
  const wasMirror = old ? old.wasMirror && norm(old.path).toLowerCase() === norm(path).toLowerCase() : before === twinText""",
     """// One edit's effect on the pending list: the edited file and its twin, each
// before and after the edit (`before` null when the file is new). The twin is
// read again after because a junctioned twin is the same file.
export function track(
  list: Drift[],
  path: string,
  twin: string,
  before: string | null,
  twinBefore: string,
  after: string,
  twinAfter: string,
): Drift[] {
  const key = pairKey(path, twin)
  const old = list.find(d => d.key === key)
  const rest = list.filter(d => d.key !== key)
  if (after === twinAfter) return rest
  // Both sides edited this turn: copying either way would drop an edit.
  const wasMirror = old ? old.wasMirror && norm(old.path).toLowerCase() === norm(path).toLowerCase() : before === twinBefore"""),
    ("""  const before = await readText($, path)
  const twinText = await readText($, twin)
  const ran = await run()
  if (ran.deny !== undefined || ran.isError || twinText === null) return ran
  const after = await readText($, path)
  if (after !== null) await update($, pending, list => track(list, path, twin, before, twinText, after))
  return ran""",
     """  const before = await readText($, path)
  const twinBefore = await readText($, twin)
  const ran = await run()
  if (ran.deny !== undefined || ran.isError || twinBefore === null) return ran
  const after = await readText($, path)
  const twinAfter = await readText($, twin)
